"""Generic synthesis with yosys (no technology library) of blocks of the digital signature IP: the number of cells and of
flip-flops per block, so that the RTL is shown to elaborate and synthesize, and the relative size of the blocks is known.
This is not an area in um^2 and not a timing result (REQ-PPA-001 needs the library of the project, section 13).
Usage: python run_synth.py [block ...]"""
import os
import re
import subprocess
import sys

V = os.path.normpath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..')).replace(chr(92), '/')
R = os.path.normpath(V + '/../rtl').replace(chr(92), '/')
H = os.path.normpath(V + '/../../019_SHA2_SHA3_Hash/rtl').replace(chr(92), '/')
S = V + '/sim/synth'
YOSYS = 'C:/Tools/oss-cad-suite/bin/yosys.exe'

HFEED = [R + '/m_vlsit_dsig_hfeed.sv']
BLOCKS = {
    'ctl': ('m_vlsit_dsig_ctl', [R + '/m_vlsit_dsig_ctl.sv'], {}),
    'key': ('m_vlsit_dsig_key', [R + '/m_vlsit_dsig_key.sv'], {'PARA_EN_KEYIF': 1, 'PARA_EN_KEYREG': 1}),
    'rng_drbg': ('m_vlsit_dsig_rng', [R + '/m_vlsit_dsig_drbg.sv', R + '/m_vlsit_dsig_rng.sv'] + HFEED, {'PARA_RNG_SRC': 1}),
    'mmul64': ('m_vlsit_dsig_mmul', [R + '/m_vlsit_dsig_mmul.sv'], {'PARA_MUL_W': 64}),
    'mmul32': ('m_vlsit_dsig_mmul', [R + '/m_vlsit_dsig_mmul.sv'], {'PARA_MUL_W': 32}),
    'axi': ('m_vlsit_dsig_axi', [R + '/m_vlsit_dsig_axi.sv'], {}),
    'hfeed': ('m_vlsit_dsig_hfeed', HFEED, {}),
    'harb': ('m_vlsit_dsig_harb', [R + '/m_vlsit_dsig_harb.sv'], {}),
}

NOABC = ('mmul64', 'mmul32')


def run(name):
    top, files, prm = BLOCKS[name]
    os.makedirs(S, exist_ok=True)
    chp = ' '.join('-set %s %d' % (k, v) for k, v in prm.items())
    # the Montgomery multiplier is synthesized without abc (abc did not finish on the 64 x 521-bit datapath in 34 min);
    # the cells are then the unoptimized yosys generic gates, which is stated in the table
    sopt = ' -noabc' if name in NOABC else ''
    rd = 'read_verilog -sv %s; ' % ' '.join(files) + ('chparam %s %s; ' % (chp, top) if prm else '')
    script = rd + 'synth -top %s -flatten%s; stat' % (top, sopt)
    log = S + '/%s.log' % name
    env = dict(os.environ)
    env['PATH'] = 'C:/Tools/oss-cad-suite/bin;C:/Tools/oss-cad-suite/lib;' + env.get('PATH', '')
    r = subprocess.run([YOSYS, '-l', log, '-p', script], capture_output=True, text=True, timeout=3600, env=env)
    txt = open(log, errors='replace').read() if os.path.exists(log) else r.stdout + r.stderr
    # the statistics of the last 'stat' (yosys 0.69 prints '<n> cells' and one line per cell type)
    last = txt[txt.rfind('Printing statistics'):]
    cells = re.findall(r'^\s+(\d+) cells$', last, re.M)
    ffs = sum(int(n) for n in re.findall(r'^\s+(\d+)\s+\$_S?DFF\w*$', last, re.M))
    lat = sum(int(n) for n in re.findall(r'^\s+(\d+)\s+\$_DLATCH\w*$', last, re.M))
    ok = r.returncode == 0 and cells and lat == 0
    return ok, (int(cells[-1]) if cells else 0), ffs, lat, (r.stderr.strip().splitlines() or [''])[-1]


def main(names):
    lines = ['# Generic synthesis of blocks (yosys, no technology library)', '',
             'Generated by `verification/env/misc/run_synth.py`. Cells are yosys generic gates after `synth -flatten`; flip-flops '
             'count the `$_DFF*` cells; a latch fails the block. Not an area and not a timing result.', '', '| Block | Top | Parameters | Result | Cells | Flip-flops | Latches |',
             '|---|---|---|---|---|---|---|']
    nfail = 0
    for n in names:
        ok, cells, ffs, lat, err = run(n)
        nfail += not ok
        top, _, prm = BLOCKS[n]
        lines.append('| %s | %s | %s | %s | %d | %d | %d |' % (n, top, (', '.join('%s=%d' % kv for kv in prm.items()) or 'defaults') + (' (synth -noabc)' if n in NOABC else ''),
                                                            'synthesized' if ok else 'FAILED: ' + err[:80], cells, ffs, lat))
        print(lines[-1], flush=True)
    open(V + '/docs/SYNTH.md', 'w', encoding='utf-8').write('\n'.join(lines) + '\n')
    print('RESULT: %s' % ('PASS' if nfail == 0 else 'FAIL'))


if __name__ == '__main__':
    main(sys.argv[1:] or list(BLOCKS))
